from collections import deque

def shortest_hops(graph, src, dst):
    q, seen = deque([(src, 0)]), {src}
    while q:
        node, d = q.popleft()
        if node == dst:
            return d
        for nb in graph.get(node, []):
            if nb not in seen:
                seen.add(nb)
                q.append((nb, d + 1))
    return -1

