import bisect, hashlib

def _h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16)

class HashRing:
    def __init__(self, nodes=(), vnodes=50):
        self.vnodes = vnodes
        self._keys, self._map = [], {}
        for n in nodes:
            self.add(n)
    def add(self, node):
        for i in range(self.vnodes):
            h = _h(f'{node}#{i}')
            bisect.insort(self._keys, h)
            self._map[h] = node
    def get(self, key):
        h = _h(key)
        i = bisect.bisect(self._keys, h) % len(self._keys)
        return self._map[self._keys[i]]

