    def __init__(self):
        self.total = 0
        self._seen = {}
    def charge(self, key, amount):
        if key in self._seen:
            if self._seen[key] != amount:
                raise ValueError('idempotency key dipakai dengan amount berbeda')
            return 'duplicate'
        self._seen[key] = amount
        self.total += amount
        return 'charged'

